fn parse(name: &str) -> crate::TriMesh3 {
    obj_as_mujoco_reads_it(obj(name)).unwrap_or_else(|e| panic!("{name}: {e}"))
}

#[test]
fn source_oracle_triangle_order_is_exact_for_each_fixture() {
    for name in [
        "reg5", "reg8", "reg100", "reg101", "reg120", "reg215", "ell", "arrow", "bow", "star", "repeat", "quad_sq", "quad_skew", "pent_xz", "pent_yz", "neg", "two_shapes", "pyr6", "pyr101", "prism_ell",
    ] {
        let mesh = parse(name);
        let want = oracle_tris(name);
        assert_eq!(mesh.tris, want, "{name}: triangle order diverged from the source build");
    }
}

#[test]
fn polygons_past_one_hundred_vertices_are_ear_clipped_not_dropped() {
    // PyPI wheel: a regular 101-gon is absent (face count would be the sentinel triangle only).
    // Source build: n-2 triangles from the n-gon, plus that sentinel.
    assert_eq!(parse("reg100").tris.len(), 99);
    assert_eq!(parse("reg101").tris.len(), 100);
    assert_eq!(parse("reg120").tris.len(), 119);
    assert_eq!(parse("reg215").tris.len(), 214);
    assert_eq!(parse("pyr101").tris.len(), 200);
}

#[test]
fn a_fan_of_the_concave_octagon_is_not_the_source_triangulation() {
    // Mutation: replacing the ear clip with a fan from vertex 0 still yields n-2 triangles
    // and the same area, and still fails this order. reg8's octagon ends
    // `5 6 7` / `0 5 7`, not the fan's `0 5 6` / `0 6 7`.
    let tris = &parse("reg8").tris;
    assert_eq!(tris[4], [5, 6, 7]);
    assert_eq!(tris[5], [0, 5, 7]);
    assert_ne!(tris[4], [0, 5, 6]);
}

#[test]
fn a_fan_of_the_arrow_is_not_the_source_triangulation() {
    // This L's ear clip happens to be the fan from vertex 0, so it cannot detect that mutation.
    // The arrow's oracle triangles are `3 4 5` and `0 3 5`, not the fan's `0 3 4` and `0 4 5`.
    let mesh = parse("arrow");
    let fan = [[0, 1, 2], [0, 2, 3], [0, 3, 4], [0, 4, 5]];
    assert_ne!(mesh.tris.as_slice(), fan.as_slice());
    assert_eq!(mesh.tris[2], [3, 4, 5]);
    assert_eq!(mesh.tris[3], [0, 3, 5]);
}

#[test]
fn malformed_faces_are_refused_and_a_collinear_face_has_no_area() {
    let err = obj_as_mujoco_reads_it("v 0 0 0\nv 1 0 0\nf 1 2\n").unwrap_err();
    assert!(err.contains("fewer than 3"), "{err}");
    let err = obj_as_mujoco_reads_it("v 0 0 0\nv 1 0 0\nv 0 1 0\nf 0 1 2\n").unwrap_err();
    assert!(err.contains("index 0"), "{err}");
    let err = obj_as_mujoco_reads_it("v 0 0 0\nv 1 0 0\nv 0 1 0\nf 1 2 9\n").unwrap_err();
    assert!(err.contains("out of range"), "{err}");
    let err = mesh_inertia_mujoco(&parse("collinear"), MeshInertia::Legacy).unwrap_err();
    assert!(err.contains("surface area"), "{err}");
}

fn compile(name: &str) -> crate::mjcf_tree::MjcfTree {
    let xml = r#"<mujoco><compiler meshdir="."/><asset><mesh name="m" file="m.obj"/></asset><worldbody><body name="b"><geom type="mesh" mesh="m" mass="1" contype="0" conaffinity="0"/></body></worldbody></mujoco>"#;
    let text = obj(name);
    tree_from_mjcf(xml, &|p: &str| (p == "m.obj").then(|| text.as_bytes().to_vec())).unwrap_or_else(|e| panic!("{name}: {e}"))
}

#[test]
fn convex_pyramids_match_the_source_compilers_mass_inertia_and_volume_bits() {
    // Diagnostic build sha256 fda4efc9… printed these volumes. Its body_inertia bits match the
    // uninstrumented oracle on these two meshes, so the volumes are comparable.
    let cases: &[(&str, [u64; 3], u64)] = &[
        ("pyr6", [0x3fcffffff65d36c0, 0x3fc4cccccccccccc, 0x3fc4ccccc32a038e], 0x3febb67ae0000000),
        ("pyr101", [0x3fd33007d90ba667, 0x3fc7fcd4a8b95c97, 0x3fc7fcd4a2f789cf], 0x3ff0be8e16fa6dd5),
    ];
    for (name, inertia, volume) in cases {
        let tree = compile(name);
        assert_eq!(tree.body_mass["b"].to_bits(), 0x3ff0000000000000, "{name} mass");
        assert_eq!(tree.body_iinertia["b"].map(f64::to_bits), *inertia, "{name} inertia");
        let (vol, _, _) = mesh_inertia_mujoco(&parse(name), MeshInertia::Legacy).unwrap();
        assert_eq!(vol.to_bits(), *volume, "{name} volume");
    }
}

/// Pyramid frames match the contract-off compiler, including the components that used to miss by an ulp.
#[test]
fn pyramid_frames_match_the_source_compiler() {
    let tree = compile("pyr6");
    let p = tree.body_ipos["b"];
    let q = tree.body_iquat_wxyz["b"];
    assert_eq!(p.x.to_bits(), 0x3c6279a74b20663c);
    assert_eq!(p.z.to_bits(), 0x3fd0000000000001);
    assert_eq!(p.y.to_bits(), 0x3c7bb67af0b09959, "oracle ipos y");
    assert_eq!(q[1].to_bits(), 0x3fe6a09e667f3bd9);
    assert_eq!(q[3].to_bits(), 0x3fe6a09e667f3bd9);
    assert_eq!(q[0].to_bits(), 0);
    assert_eq!(q[2].to_bits(), 0);
    let tree = compile("pyr101");
    let p = tree.body_ipos["b"];
    assert_eq!(p.x.to_bits(), 0xbdd7015627fe8558);
    assert_eq!(p.y.to_bits(), 0xbc5bf320a662a454);
    assert_eq!(p.z.to_bits(), 0x3fcffffffffffffe);
}

/// The L prism's triangles and principal moments match the contract-off source build.
#[test]
fn ell_prism_inertia_matches_the_source_compiler() {
    let tree = compile("prism_ell");
    let got = tree.body_iinertia["b"].map(f64::to_bits);
    let oracle = [0x3ff668bdbb5a3878, 0x3ff1f8c6d9f8c6db, 0x3fdc28552406106d];
    assert_eq!(tree.body_mass["b"].to_bits(), 0x3ff0000000000000);
    assert_eq!(got, oracle);
}

